        "text": "本文提到的相关内容仅作科普用途，不作为医疗产品的推荐或功效证明。如有相关症状请及时就医，寻求专业意见，请仔细阅读产品说明书或者在医务人员的指导下购买和使用，禁忌内容或者注意事项详见说明书。"
